     1→"use client";
     2→
     3→import React, { useMemo } from "react";
     4→import { useTranslations } from "next-intl";
     5→import { cn } from "@/lib/utils";
     6→import type { GlobalAudioTrack } from "@/lib/player/globalAudioPlayer";
     7→import { formatTime } from "./utils";
     8→
     9→type SoundCloudTrackListProps = {
    10→  tracks: GlobalAudioTrack[];
    11→  currentTrackId?: number | null;
    12→  currentIndex?: number | null;
    13→  isPlaying?: boolean;
    14→  isLoading?: boolean;
    15→  disabled?: boolean;
    16→  onSelect?: (index: number) => void;
    17→  className?: string;
    18→};
    19→
    20→const formatTrackNumber = (index: number) => String(index + 1).padStart(2, "0");
    21→
    22→export const SoundCloudTrackList: React.FC<SoundCloudTrackListProps> = ({
    23→  tracks,
    24→  currentTrackId,
    25→  currentIndex,
    26→  isPlaying = false,
    27→  isLoading = false,
    28→  disabled = false,
    29→  onSelect,
    30→  className,
    31→}) => {
    32→  const t = useTranslations("musicPlayer");
    33→
    34→  const items = useMemo(() => {
    35→    return Array.isArray(tracks) ? tracks : [];
    36→  }, [tracks]);
    37→
    38→  if (isLoading && items.length === 0) {
    39→    return (
    40→      <div className={cn("font-mono text-xs text-neo-text/60 px-3 py-3", className)}>
    41→        {t("tracklist.loading")}
    42→      </div>
    43→    );
    44→  }
    45→
    46→  if (items.length === 0) {
    47→    return (
    48→      <div className={cn("font-mono text-xs text-neo-text/60 px-3 py-3", className)}>
    49→        {t("tracklist.empty")}
    50→      </div>
    51→    );
    52→  }
    53→
    54→  const clickDisabled = disabled || !onSelect;
    55→
    56→  return (
    57→    <div className={cn("max-h-52 overflow-auto px-3 py-3", className)}>
    58→      <ul className="space-y-2">
    59→        {items.map((track, index) => {
    60→          const isActive =
    61→            (typeof currentTrackId === "number" && currentTrackId === track.id) ||
    62→            (typeof currentIndex === "number" && currentIndex === index);
    63→
    64→          return (
    65→            <li key={track.id}>
    66→              <button
    67→                type="button"
    68→                onClick={() => onSelect?.(index)}
    69→                disabled={clickDisabled}
    70→                aria-current={isActive ? "true" : undefined}
    71→                className={cn(
    72→                  "w-full flex items-center gap-3 text-left",
    73→                  "px-3 py-2 border-2 border-neo-border",
    74→                  "bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
    75→                  "hover:-translate-y-0.5 transition-transform",
    76→                  isActive &&
    77→                    "bg-neo-accent text-neo-text-inverse shadow-[3px_3px_0px_0px_var(--neo-border)]",
    78→                  clickDisabled &&
    79→                    "opacity-50 cursor-not-allowed hover:translate-y-0 hover:shadow-[3px_3px_0px_0px_var(--neo-shadow)]"
    80→                )}
    81→              >
    82→                <span
    83→                  className={cn(
    84→                    "w-8 flex-shrink-0 font-mono text-[10px] uppercase tracking-[0.22em]",
    85→                    isActive ? "text-white/80" : "text-neo-text/50"
    86→                  )}
    87→                >
    88→                  {formatTrackNumber(index)}
    89→                </span>
    90→
    91→                <span className="min-w-0 flex-1">
    92→                  <span className="block font-black uppercase tracking-tight truncate">
    93→                    {track.title}
    94→                  </span>
    95→                </span>
    96→
    97→                {typeof track.durationMs === "number" && track.durationMs > 0 && (
    98→                  <span
    99→                    className={cn(
   100→                      "flex-shrink-0 font-mono text-[10px] uppercase tracking-[0.18em]",
   101→                      isActive ? "text-white/70" : "text-neo-text/50"
   102→                    )}
   103→                  >
   104→                    {formatTime(track.durationMs)}
   105→                  </span>
   106→                )}
   107→
   108→                <span
   109→                  aria-hidden="true"
   110→                  className={cn(
   111→                    "h-2.5 w-2.5 border-2 border-neo-border flex-shrink-0",
   112→                    isActive ? "bg-neo-text-inverse" : "bg-neo-accent",
   113→                    isActive && isPlaying && "animate-pulse"
   114→                  )}
   115→                />
   116→              </button>
   117→            </li>
   118→          );
   119→        })}
   120→      </ul>
   121→    </div>
   122→  );
   123→};
   124→

