     1→"use client";
     2→
     3→import React, { useCallback, useId, useMemo, useRef, useState } from "react";
     4→import { cn } from "@/lib/utils";
     5→
     6→type SoundCloudWaveformProps = {
     7→  samples: number[] | null;
     8→  progress: number;
     9→  disabled?: boolean;
    10→  onSeek?: (ratio: number) => void;
    11→  className?: string;
    12→  height?: number;
    13→};
    14→
    15→const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
    16→
    17→export const SoundCloudWaveform: React.FC<SoundCloudWaveformProps> = ({
    18→  samples,
    19→  progress,
    20→  disabled = false,
    21→  onSeek,
    22→  className,
    23→  height = 36,
    24→}) => {
    25→  const clipId = useId();
    26→  const containerRef = useRef<HTMLDivElement | null>(null);
    27→  const [isDragging, setIsDragging] = useState(false);
    28→
    29→  const bars = useMemo(() => {
    30→    if (!samples || samples.length === 0) return Array.from({ length: 72 }, () => 0.25);
    31→    return samples;
    32→  }, [samples]);
    33→
    34→  const viewWidth = bars.length;
    35→  const safeProgress = clamp01(progress);
    36→
    37→  const seekFromEvent = useCallback(
    38→    (event: React.PointerEvent) => {
    39→      if (!containerRef.current || !onSeek || disabled) return;
    40→      const rect = containerRef.current.getBoundingClientRect();
    41→      const x = event.clientX - rect.left;
    42→      const ratio = rect.width ? x / rect.width : 0;
    43→      onSeek(clamp01(ratio));
    44→    },
    45→    [disabled, onSeek]
    46→  );
    47→
    48→  return (
    49→    <div
    50→      ref={containerRef}
    51→      className={cn(
    52→        "relative w-full select-none touch-none",
    53→        !disabled && onSeek ? "cursor-pointer" : "cursor-default",
    54→        className
    55→      )}
    56→      style={{ height }}
    57→      onPointerDown={(e) => {
    58→        if (!onSeek || disabled) return;
    59→        setIsDragging(true);
    60→        (e.currentTarget as HTMLDivElement).setPointerCapture(e.pointerId);
    61→        seekFromEvent(e);
    62→      }}
    63→      onPointerMove={(e) => {
    64→        if (!isDragging) return;
    65→        seekFromEvent(e);
    66→      }}
    67→      onPointerUp={(e) => {
    68→        if (!isDragging) return;
    69→        setIsDragging(false);
    70→        try {
    71→          (e.currentTarget as HTMLDivElement).releasePointerCapture(e.pointerId);
    72→        } catch {
    73→          // noop
    74→        }
    75→      }}
    76→      onPointerCancel={() => setIsDragging(false)}
    77→      aria-hidden="true"
    78→    >
    79→      <svg
    80→        width="100%"
    81→        height="100%"
    82→        viewBox={`0 0 ${viewWidth} 1`}
    83→        preserveAspectRatio="none"
    84→        className="block"
    85→      >
    86→        <defs>
    87→          <clipPath id={clipId}>
    88→            <rect x="0" y="0" width={viewWidth * safeProgress} height="1" />
    89→          </clipPath>
    90→        </defs>
    91→
    92→        {/* Background bars */}
    93→        {bars.map((value, i) => {
    94→          const h = Math.max(0.06, Math.min(1, value));
    95→          const y = (1 - h) / 2;
    96→          return (
    97→            <rect
    98→              key={`bg-${i}`}
    99→              x={i + 0.15}
   100→              y={y}
   101→              width={0.7}
   102→              height={h}
   103→              rx={0.2}
   104→              fill="currentColor"
   105→              opacity={disabled ? 0.15 : 0.25}
   106→              className="text-neo-text"
   107→            />
   108→          );
   109→        })}
   110→
   111→        {/* Progress bars */}
   112→        <g clipPath={`url(#${clipId})`}>
   113→          {bars.map((value, i) => {
   114→            const h = Math.max(0.06, Math.min(1, value));
   115→            const y = (1 - h) / 2;
   116→            return (
   117→              <rect
   118→                key={`fg-${i}`}
   119→                x={i + 0.15}
   120→                y={y}
   121→                width={0.7}
   122→                height={h}
   123→                rx={0.2}
   124→                fill="currentColor"
   125→                opacity={disabled ? 0.4 : 0.95}
   126→                className="text-neo-accent"
   127→              />
   128→            );
   129→          })}
   130→        </g>
   131→
   132→        {/* Playhead */}
   133→        <rect
   134→          x={viewWidth * safeProgress - 0.35}
   135→          y={0}
   136→          width={0.7}
   137→          height={1}
   138→          fill="currentColor"
   139→          className="text-neo-accent"
   140→          opacity={disabled ? 0.35 : 0.9}
   141→        />
   142→      </svg>
   143→    </div>
   144→  );
   145→};
