     1→"use client";
     2→
     3→import React, { useEffect, useMemo, useRef, useState } from "react";
     4→import { AnimatePresence, motion } from "framer-motion";
     5→import {
     6→  ChevronDown,
     7→  ChevronUp,
     8→  ExternalLink,
     9→  Pause,
    10→  Play,
    11→  SkipBack,
    12→  SkipForward,
    13→  Volume2,
    14→  VolumeX,
    15→  X,
    16→} from "lucide-react";
    17→import Image from "next/image";
    18→import { useTranslations } from "next-intl";
    19→import { usePathname } from "next/navigation";
    20→import { useConsent } from "../legal/ConsentProvider";
    21→import { useSoundCloudWaveform } from "@/lib/hooks/useSoundCloudWaveform";
    22→import { SOUND_CLOUD_PROFILE_URL, useGlobalAudioPlayer } from "@/lib/player/globalAudioPlayer";
    23→import { cn } from "@/lib/utils";
    24→import { SoundCloudIcon } from "./SoundCloudIcon";
    25→import { SoundCloudTrackList } from "./SoundCloudTrackList";
    26→import { SoundCloudWaveform } from "./SoundCloudWaveform";
    27→import { formatTime } from "./utils";
    28→
    29→const isHomePathname = (pathname: string | null) => {
    30→  const path = pathname ?? "";
    31→  return /^\/(en|fr)$/.test(path);
    32→};
    33→
    34→const normalizeArtworkUrl = (url: string | null | undefined, size: "t200x200" | "t500x500") => {
    35→  if (!url) return null;
    36→  return url.replace("-large", `-${size}`);
    37→};
    38→
    39→export const GlobalAudioPlayerBar = () => {
    40→  const t = useTranslations("musicPlayer");
    41→  const pathname = usePathname();
    42→  const isHome = isHomePathname(pathname);
    43→
    44→  const { openManager } = useConsent();
    45→  const {
    46→    status,
    47→    mediaAllowed,
    48→    hasStarted,
    49→    isDismissed,
    50→    isPlaying,
    51→    track,
    52→    queue,
    53→    currentIndex,
    54→    positionMs,
    55→    durationMs,
    56→    volume,
    57→    error,
    58→    actions,
    59→  } = useGlobalAudioPlayer();
    60→
    61→  const [isCollapsed, setIsCollapsed] = useState(true);
    62→  const [lastNonZeroVolume, setLastNonZeroVolume] = useState(80);
    63→
    64→  const [showOnHome, setShowOnHome] = useState(false);
    65→
    66→  useEffect(() => {
    67→    if (!isHome) {
    68→      setShowOnHome(true);
    69→      return;
    70→    }
    71→
    72→    const heroSelector = '[data-hero-audio-player="true"]';
    73→    const showThreshold = 0.15;
    74→
    75→    let raf = 0;
    76→    let rafScroll = 0;
    77→    let observer: IntersectionObserver | null = null;
    78→    let detachScrollFallback: (() => void) | null = null;
    79→
    80→    const installScrollFallback = () => {
    81→      const update = () => {
    82→        const threshold = Math.max(520, Math.floor(window.innerHeight * 0.9));
    83→        setShowOnHome(window.scrollY > threshold);
    84→      };
    85→
    86→      const onScroll = () => {
    87→        if (rafScroll) return;
    88→        rafScroll = window.requestAnimationFrame(() => {
    89→          rafScroll = 0;
    90→          update();
    91→        });
    92→      };
    93→
    94→      update();
    95→      window.addEventListener("scroll", onScroll, { passive: true });
    96→      window.addEventListener("resize", onScroll, { passive: true });
    97→      detachScrollFallback = () => {
    98→        window.removeEventListener("scroll", onScroll);
    99→        window.removeEventListener("resize", onScroll);
   100→        if (rafScroll) window.cancelAnimationFrame(rafScroll);
   101→      };
   102→    };
   103→
   104→    const attachObserver = () => {
   105→      const heroEl = document.querySelector(heroSelector);
   106→      if (!heroEl) {
   107→        raf = window.requestAnimationFrame(attachObserver);
   108→        return;
   109→      }
   110→
   111→      if (typeof IntersectionObserver === "undefined") {
   112→        installScrollFallback();
   113→        return;
   114→      }
   115→
   116→      observer = new IntersectionObserver(
   117→        (entries) => {
   118→          const entry = entries[0];
   119→          if (!entry) return;
   120→          setShowOnHome(!entry.isIntersecting || entry.intersectionRatio < showThreshold);
   121→        },
   122→        { threshold: [0, 0.05, showThreshold, 0.25, 0.5, 0.75, 1] }
   123→      );
   124→
   125→      observer.observe(heroEl);
   126→    };
   127→
   128→    attachObserver();
   129→
   130→    return () => {
   131→      if (raf) window.cancelAnimationFrame(raf);
   132→      detachScrollFallback?.();
   133→      observer?.disconnect();
   134→    };
   135→  }, [isHome]);
   136→
   137→  useEffect(() => {
   138→    if (volume > 0) setLastNonZeroVolume(volume);
   139→  }, [volume]);
   140→
   141→  const shouldShowBar = hasStarted && !isDismissed && (!isHome || showOnHome);
   142→  const shouldShowReopen = hasStarted && isDismissed;
   143→
   144→  const progress = durationMs > 0 ? Math.min(1, positionMs / durationMs) : 0;
   145→  const remainingMs = Math.max(0, durationMs - positionMs);
   146→  const externalUrl = track?.permalinkUrl || SOUND_CLOUD_PROFILE_URL;
   147→  const artworkUrl = normalizeArtworkUrl(track?.artworkUrl ?? null, "t200x200");
   148→
   149→  const { samples, isLoading: isWaveformLoading } = useSoundCloudWaveform(
   150→    mediaAllowed ? track?.waveformUrl : null,
   151→    track?.id,
   152→    96
   153→  );
   154→
   155→  const displayTitle = track?.title || t("status.noTrack");
   156→  const displayArtist = track?.artist || t("status.soundcloud");
   157→
   158→  const isPlayerUnavailable = status === "error" || !!error;
   159→  const controlsDisabled = !mediaAllowed || status !== "ready" || isPlayerUnavailable;
   160→
   161→  const statusLabel = useMemo(() => {
   162→    if (!mediaAllowed) return t("status.mediaDisabled");
   163→    if (isPlayerUnavailable) return t("status.unavailable");
   164→    if (status === "loading") return t("status.loading");
   165→    return isPlaying ? t("status.playing") : t("status.paused");
   166→  }, [isPlayerUnavailable, isPlaying, mediaAllowed, status, t]);
   167→
   168→  const bottomOffsetPx = 12;
   169→  const pageGapPx = 12;
   170→  const barMeasureRef = useRef<HTMLDivElement | null>(null);
   171→  const [measuredHeightPx, setMeasuredHeightPx] = useState(0);
   172→
   173→  useEffect(() => {
   174→    if (!shouldShowBar) {
   175→      setMeasuredHeightPx(0);
   176→      return;
   177→    }
   178→
   179→    const el = barMeasureRef.current;
   180→    if (!el) return;
   181→
   182→    const update = () => setMeasuredHeightPx(Math.ceil(el.getBoundingClientRect().height));
   183→    update();
   184→
   185→    if (typeof ResizeObserver === "undefined") {
   186→      window.addEventListener("resize", update);
   187→      return () => window.removeEventListener("resize", update);
   188→    }
   189→
   190→    const ro = new ResizeObserver(() => update());
   191→    ro.observe(el);
   192→    return () => ro.disconnect();
   193→  }, [shouldShowBar]);
   194→
   195→  const fallbackHeightPx = isCollapsed ? 96 : 320;
   196→  const spacerHeightPx = (measuredHeightPx || fallbackHeightPx) + bottomOffsetPx + pageGapPx;
   197→
   198→  return (
   199→    <>
   200→      {shouldShowBar && (
   201→        <div
   202→          aria-hidden="true"
   203→          style={{ height: `calc(${spacerHeightPx}px + env(safe-area-inset-bottom))` }}
   204→        />
   205→      )}
   206→
   207→      <AnimatePresence>
   208→        {shouldShowBar && (
   209→          <motion.div
   210→            initial={{ y: 120, opacity: 0 }}
   211→            animate={{ y: 0, opacity: 1 }}
   212→            exit={{ y: 120, opacity: 0 }}
   213→            transition={{ duration: 0.35, ease: [0.25, 0.4, 0.25, 1] }}
   214→            className="fixed inset-x-0 z-40 px-3 md:px-6"
   215→            style={{ bottom: `calc(${bottomOffsetPx}px + env(safe-area-inset-bottom))` }}
   216→          >
   217→            <div className="mx-auto max-w-6xl">
   218→              <div className="relative">
   219→                <div className="absolute -top-2 -left-2 w-full h-full border-4 border-neo-border bg-neo-bg -z-10" />
   220→
   221→                <div
   222→                  ref={barMeasureRef}
   223→                  className="border-4 border-neo-border bg-neo-surface shadow-[10px_10px_0px_0px_var(--neo-accent)] overflow-hidden"
   224→                >
   225→                  <div className="flex flex-col sm:flex-row sm:items-center gap-3 md:gap-4 p-3 md:p-4">
   226→                    {/* Track info */}
   227→                    <div className="flex items-center gap-3 min-w-0 flex-1 w-full">
   228→                      <div className="h-11 w-11 md:h-12 md:w-12 border-2 border-neo-border bg-neo-surface shadow-[3px_3px_0px_0px_var(--neo-shadow)] overflow-hidden flex-shrink-0">
   229→                        {artworkUrl ? (
   230→                          <Image
   231→                            src={artworkUrl}
   232→                            alt=""
   233→                            width={48}
   234→                            height={48}
   235→                            className="h-full w-full object-cover"
   236→                            draggable={false}
   237→                            referrerPolicy="no-referrer"
   238→                          />
   239→                        ) : (
   240→                          <div className="h-full w-full flex items-center justify-center bg-neo-text text-neo-text-inverse">
   241→                            <SoundCloudIcon className="w-5 h-5" />
   242→                          </div>
   243→                        )}
   244→                      </div>
   245→                      <div className="min-w-0">
   246→                        <div className="font-mono text-[10px] uppercase tracking-[0.2em] text-neo-accent">
   247→                          {statusLabel}
   248→                        </div>
   249→                        <div className="font-black uppercase tracking-tight text-neo-text line-clamp-2 sm:line-clamp-1">
   250→                          {displayTitle}
   251→                        </div>
   252→                        <div className="font-mono text-xs text-neo-text/60 line-clamp-1">
   253→                          {displayArtist}
   254→                        </div>
   255→                      </div>
   256→                    </div>
   257→
   258→                    {/* Controls */}
   259→                    <div className="flex items-center gap-2 md:gap-3 flex-shrink-0 w-full sm:w-auto flex-wrap sm:flex-nowrap justify-between sm:justify-start">
   260→                      <button
   261→                        type="button"
   262→                        onClick={() => actions.previous()}
   263→                        disabled={controlsDisabled}
   264→                        aria-label={t("controls.previous")}
   265→                        className={cn(
   266→                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
   267→                          "hover:-translate-y-0.5 transition-transform",
   268→                          "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
   269→                        )}
   270→                      >
   271→                        <SkipBack className="w-5 h-5 mx-auto" />
   272→                      </button>
   273→
   274→                      <button
   275→                        type="button"
   276→                        onClick={() => {
   277→                          if (!mediaAllowed) {
   278→                            openManager();
   279→                            return;
   280→                          }
   281→                          actions.toggle();
   282→                        }}
   283→                        aria-label={isPlaying ? t("controls.pause") : t("controls.play")}
   284→                        className={cn(
   285→                          "h-11 w-11 sm:h-12 sm:w-12 border-3 border-neo-border bg-neo-accent text-neo-text-inverse",
   286→                          "shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 transition-transform",
   287→                          !mediaAllowed && "bg-neo-text text-neo-text-inverse"
   288→                        )}
   289→                      >
   290→                        {isPlaying ? (
   291→                          <Pause className="w-6 h-6 mx-auto" />
   292→                        ) : (
   293→                          <Play className="w-6 h-6 mx-auto translate-x-[1px]" />
   294→                        )}
   295→                      </button>
   296→
   297→                      <button
   298→                        type="button"
   299→                        onClick={() => actions.next()}
   300→                        disabled={controlsDisabled}
   301→                        aria-label={t("controls.next")}
   302→                        className={cn(
   303→                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
   304→                          "hover:-translate-y-0.5 transition-transform",
   305→                          "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
   306→                        )}
   307→                      >
   308→                        <SkipForward className="w-5 h-5 mx-auto" />
   309→                      </button>
   310→
   311→                      {/* Volume */}
   312→                      <button
   313→                        type="button"
   314→                        onClick={() => {
