   164→export const fetchFullSoundCloudQueue = async (): Promise<boolean> => {
   165→  if (hasFetchedFullQueue || isFetchingQueue) return hasFetchedFullQueue;
   166→
   167→  isFetchingQueue = true;
   168→  try {
   169→    const res = await fetch("/api/soundcloud/tracks");
   170→    if (!res.ok) {
   171→      isFetchingQueue = false;
   172→      return false;
   173→    }
   174→
   175→    const data = await res.json();
   176→    if (!data.tracks || !Array.isArray(data.tracks)) {
   177→      isFetchingQueue = false;
   178→      return false;
   179→    }
   180→
   181→    const currentState = getGlobalAudioPlayerState();
   182→    const widgetQueue = currentState.queue;
   183→
   184→    // Build a map of track ID to widget index for quick lookup
   185→    const widgetIndexMap = new Map<number, number>();
   186→    widgetQueue.forEach((wt) => {
   187→      if (typeof wt.widgetIndex === "number") {
   188→        widgetIndexMap.set(wt.id, wt.widgetIndex);
   189→      }
   190→    });
   191→
   192→    // Map API tracks and find widget indices by matching track IDs
   193→    const mappedTracks: GlobalAudioTrack[] = (data.tracks as ApiTrack[]).map((track) => {
   194→      const widgetIndex = widgetIndexMap.get(track.id);
   195→      return {
   196→        id: track.id,
   197→        title: track.title,
   198→        artist: track.artist,
   199→        artworkUrl: track.artworkUrl,
   200→        waveformUrl: track.waveformUrl,
   201→        permalinkUrl: track.permalinkUrl,
   202→        durationMs: track.durationMs,
   203→        // Only set widgetIndex if track is in widget's range (first 20)
   204→        widgetIndex: widgetIndex !== undefined ? widgetIndex : undefined,
   205→      };
   206→    });
   207→
   208→    setGlobalAudioPlayerQueue(mappedTracks);
   209→
   210→    // Update current index if we have a current track
   211→    const currentId = currentState.track?.id;
   212→    if (typeof currentId === "number") {
   213→      const idx = mappedTracks.findIndex((t) => t.id === currentId);
   214→      if (idx >= 0) setGlobalAudioPlayerCurrentIndex(idx);
   215→    } else if (mappedTracks.length > 0) {
   216→      // No track selected yet, set the first track as the current one
   217→      setGlobalAudioPlayerTrack(mappedTracks[0]);
   218→      setGlobalAudioPlayerCurrentIndex(0);
   219→    }
   220→
   221→    hasFetchedFullQueue = true;
   222→    isFetchingQueue = false;
   223→    return true;
   224→  } catch (error) {
   225→    // eslint-disable-next-line no-console
   226→    console.error("Failed to fetch SoundCloud tracks:", error);
   227→    isFetchingQueue = false;
   228→    return false;
   229→  }
   230→};
