   292→export const tryConsumePendingGlobalAudioPlayerAction = () => {
   293→  if (!widget) return false;
   294→  if (!pendingAction) return false;
   295→  const isFresh = Date.now() - pendingAction.requestedAt <= PENDING_ACTION_TTL_MS;
   296→  const action = pendingAction;
   297→  pendingAction = null;
   298→  if (!isFresh) return false;
   299→
   300→  if (action.type === "select") {
   301→    try {
   302→      widget.skip(action.widgetIndex);
   303→      widget.play();
   304→      return true;
   305→    } catch {
   306→      return false;
   307→    }
   308→  }
   309→
   310→  if (action.type === "play") {
   311→    widget.play();
   312→    return true;
   313→  }
   314→  if (action.type === "toggle") {
   315→    widget.toggle();
   316→    return true;
   317→  }
   318→  return false;
   319→};
   320→
   321→const canControlWidget = () => !!widget && state.status === "ready" && state.mediaAllowed;
   322→
   323→const resolveCurrentIndex = () => {
   324→  if (typeof state.currentIndex === "number") return state.currentIndex;
   325→  const currentId = state.track?.id;
   326→  if (typeof currentId !== "number") return null;
   327→  const idx = state.queue.findIndex((t) => t.id === currentId);
   328→  return idx >= 0 ? idx : null;
   329→};
   330→
   331→export const globalAudioPlayerActions = {
   332→  play: () => {
   333→    queueGlobalAudioPlayerAction("play");
   334→    if (!canControlWidget()) return;
   335→    widget?.play();
   336→  },
   337→  pause: () => {
   338→    if (!canControlWidget()) return;
   339→    widget?.pause();
   340→  },
   341→  setVolume: (volume: number) => {
   342→    setGlobalAudioPlayerVolume(volume);
   343→  },
   344→  toggle: () => {
   345→    queueGlobalAudioPlayerAction("toggle");
   346→    if (!canControlWidget()) return;
   347→    widget?.toggle();
   348→  },
   349→  next: () => {
   350→    const { queue } = state;
   351→    const idx = resolveCurrentIndex();
   352→    if (queue.length && typeof idx === "number") {
   353→      globalAudioPlayerActions.selectTrack((idx + 1) % queue.length);
   354→      return;
   355→    }
   356→    if (!canControlWidget()) return;
   357→    widget?.next();
   358→  },
   359→  previous: () => {
   360→    const { queue } = state;
   361→    const idx = resolveCurrentIndex();
   362→    if (queue.length && typeof idx === "number") {
   363→      globalAudioPlayerActions.selectTrack((idx - 1 + queue.length) % queue.length);
   364→      return;
   365→    }
   366→    if (!canControlWidget()) return;
   367→    widget?.prev();
   368→  },
   369→  selectTrack: (index: number) => {
   370→    const safeIndex = Math.max(0, Math.floor(index));
   371→    const boundedIndex =
   372→      state.queue.length > 0 ? Math.min(safeIndex, state.queue.length - 1) : safeIndex;
   373→    setGlobalAudioPlayerCurrentIndex(boundedIndex);
   374→    const nextTrack = state.queue[boundedIndex];
   375→    if (nextTrack) setGlobalAudioPlayerTrack(nextTrack);
   376→    setGlobalAudioPlayerProgress(0);
   377→
   378→    const widgetIndex = nextTrack?.widgetIndex;
   379→    const isInWidgetRange = typeof widgetIndex === "number" && widgetIndex >= 0 && widgetIndex < 20;
   380→
   381→    if (!canControlWidget()) {
   382→      // Queue action for when widget becomes ready
   383→      if (isInWidgetRange && typeof widgetIndex === "number") {
   384→        queueGlobalAudioPlayerSelectTrack(widgetIndex);
   385→      }
   386→      return;
   387→    }
   388→
   389→    try {
   390→      if (isInWidgetRange && typeof widgetIndex === "number") {
   391→        // Track is in widget's loaded range, use skip
   392→        widget?.skip(widgetIndex);
   393→        widget?.play();
   394→      } else if (nextTrack?.permalinkUrl) {
   395→        // Track is beyond widget range, load it directly
   396→        widget?.load(nextTrack.permalinkUrl, { auto_play: true });
   397→      }
   398→    } catch {
   399→      // noop
   400→    }
   401→  },
   402→  open: () => {
   403→    setGlobalAudioPlayerDismissed(false);
   404→  },
   405→  dismiss: () => {
   406→    setGlobalAudioPlayerDismissed(true);
   407→    setGlobalAudioPlayerPlaying(false);
   408→    try {
   409→      widget?.pause();
   410→    } catch {
   411→      // noop
   412→    }
   413→  },
   414→  seekTo: (milliseconds: number) => {
   415→    if (!canControlWidget()) return;
   416→    const clamped = Math.max(0, Math.floor(milliseconds));
   417→    widget?.seekTo(clamped);
   418→    setGlobalAudioPlayerProgress(clamped);
   419→  },
   420→  seekToRatio: (ratio: number) => {
   421→    if (!state.durationMs) return;
   422→    const clampedRatio = Math.max(0, Math.min(1, ratio));
   423→    globalAudioPlayerActions.seekTo(Math.floor(state.durationMs * clampedRatio));
   424→  },
   425→};
   426→
   427→export const useGlobalAudioPlayer = () => {
   428→  const snapshot = useSyncExternalStore(
   429→    subscribeGlobalAudioPlayer,
   430→    getGlobalAudioPlayerState,
   431→    getGlobalAudioPlayerState
   432→  );
   433→
   434→  return useMemo(
   435→    () => ({
   436→      ...snapshot,
   437→      actions: globalAudioPlayerActions,
   438→    }),
   439→    [snapshot]
   440→  );
   441→};
