    79→  const [samples, setSamples] = useState<number[] | null>(null);
    80→  const [source, setSource] = useState<WaveformSource>("none");
    81→  const [isLoading, setIsLoading] = useState(false);
    82→
    83→  const fallbackSeed = useMemo(() => {
    84→    if (typeof soundId === "number") return soundId;
    85→    if (waveformUrl) return hashString(waveformUrl);
    86→    return 1337;
    87→  }, [soundId, waveformUrl]);
    88→
    89→  useEffect(() => {
    90→    const fallback = () => {
    91→      setSamples(generateFallbackWaveform(fallbackSeed, barsCount));
    92→      setSource(waveformUrl ? "fallback" : "none");
    93→      setIsLoading(false);
    94→    };
    95→
    96→    if (!waveformUrl) {
    97→      fallback();
    98→      return;
    99→    }
   100→
   101→    const cached = waveformCache.get(waveformUrl);
   102→    if (cached) {
   103→      setSamples(cached);
   104→      setSource("soundcloud");
   105→      setIsLoading(false);
   106→      return;
   107→    }
   108→
   109→    const controller = new AbortController();
   110→    setIsLoading(true);
   111→
   112→    fetch(waveformUrl, { signal: controller.signal })
   113→      .then((res) => {
   114→        if (!res.ok) throw new Error(`Waveform fetch failed: ${res.status}`);
   115→        return res.json() as Promise<{ samples?: number[] }>;
   116→      })
   117→      .then((data) => {
   118→        const rawSamples = Array.isArray(data.samples) ? data.samples : null;
   119→        if (!rawSamples) {
   120→          fallback();
   121→          return;
   122→        }
   123→        const normalized = resampleMax(rawSamples, barsCount);
   124→        waveformCache.set(waveformUrl, normalized);
   125→        setSamples(normalized);
   126→        setSource("soundcloud");
   127→        setIsLoading(false);
   128→      })
   129→      .catch((err) => {
   130→        if (err?.name === "AbortError") return;
   131→        fallback();
   132→      });
   133→
   134→    return () => controller.abort();
   135→  }, [barsCount, fallbackSeed, waveformUrl]);
   136→
