     3→const SOUNDCLOUD_PROFILE_URL = "https://soundcloud.com/loic-ghanem";
     4→const CACHE_TTL_SECONDS = 3600; // 1 hour
     5→
     6→type SoundCloudTrack = {
     7→  id: number;
     8→  title: string;
