    96→async function resolveUser(clientId: string): Promise<SoundCloudUser | null> {
    97→  const url = `https://api-v2.soundcloud.com/resolve?url=${encodeURIComponent(
    98→    SOUNDCLOUD_PROFILE_URL
    99→  )}&client_id=${clientId}`;
   100→
   101→  const res = await fetch(url);
   102→  if (!res.ok) return null;
   103→  return res.json();
   104→}
   105→
   106→async function fetchAllTracks(userId: number, clientId: string): Promise<SoundCloudTrack[]> {
   107→  const allTracks: SoundCloudTrack[] = [];
   108→  const limit = 200;
   109→  let offset = 0;
   110→  let hasMore = true;
   111→
   112→  while (hasMore) {
   113→    const url = `https://api-v2.soundcloud.com/users/${userId}/tracks?client_id=${clientId}&limit=${limit}&offset=${offset}&linked_partitioning=1`;
   114→    const res = await fetch(url);
   115→
   116→    if (!res.ok) break;
   117→
   118→    const data: SoundCloudTracksResponse = await res.json();
   119→    if (data.collection && data.collection.length > 0) {
   120→      allTracks.push(...data.collection);
   121→      offset += data.collection.length;
   122→      hasMore = !!data.next_href && data.collection.length === limit;
   123→    } else {
   124→      hasMore = false;
   125→    }
   126→
   127→    // Safety limit
   128→    if (allTracks.length > 1000) break;
   129→  }
   130→
   131→  return allTracks;
   132→}
   133→
   134→function mapTrack(track: SoundCloudTrack) {
   135→  return {
   136→    id: track.id,
   137→    title: track.title,
   138→    artist: track.user?.username ?? "Unknown",
   139→    artworkUrl: track.artwork_url,
   140→    waveformUrl: track.waveform_url,
   141→    permalinkUrl: track.permalink_url,
   142→    durationMs: track.duration,
   143→    createdAt: track.created_at,
   144→    displayDate: track.display_date,
   145→    releaseDate: track.release_date,
   146→  };
   147→}
