   149→export async function GET() {
   150→  try {
   151→    const clientId = await getClientId();
   152→    if (!clientId) {
   153→      return NextResponse.json(
   154→        { error: "Unable to retrieve SoundCloud client ID" },
   155→        { status: 503 }
   156→      );
   157→    }
   158→
   159→    const user = await resolveUser(clientId);
   160→    if (!user) {
   161→      return NextResponse.json({ error: "Unable to resolve SoundCloud user" }, { status: 404 });
   162→    }
   163→
   164→    const tracks = await fetchAllTracks(user.id, clientId);
   165→
   166→    // Sort by date (most recent first)
   167→    const sortedTracks = tracks.sort((a, b) => {
   168→      const dateA = new Date(a.release_date || a.display_date || a.created_at).getTime();
   169→      const dateB = new Date(b.release_date || b.display_date || b.created_at).getTime();
   170→      return dateB - dateA;
   171→    });
   172→
   173→    const mappedTracks = sortedTracks.map(mapTrack);
   174→
   175→    return NextResponse.json(
   176→      {
   177→        tracks: mappedTracks,
   178→        total: mappedTracks.length,
   179→        user: {
   180→          id: user.id,
   181→          username: user.username,
   182→          trackCount: user.track_count,
   183→        },
   184→      },
   185→      {
   186→        headers: {
   187→          "Cache-Control": `public, s-maxage=${CACHE_TTL_SECONDS}, stale-while-revalidate=86400`,
   188→        },
   189→      }
   190→    );
   191→  } catch (error) {
   192→    // eslint-disable-next-line no-console
   193→    console.error("SoundCloud API error:", error);
   194→    return NextResponse.json({ error: "Failed to fetch SoundCloud tracks" }, { status: 500 });
   195→  }
   196→}
