     4→  const totalSeconds = Math.max(0, Math.floor(milliseconds / 1000));
     5→  const hours = Math.floor(totalSeconds / 3600);
     6→  const minutes = Math.floor((totalSeconds % 3600) / 60);
     7→  const seconds = totalSeconds % 60;
     8→
     9→  if (hours > 0) {
    10→    return `${hours}:${minutes.toString().padStart(2, "0")}:${seconds.toString().padStart(2, "0")}`;
